<?php declare(strict_types=1);
require_once __DIR__.'/../../../src/Finance/Invoices/InvoicePositionReview.php';
if(!isset($invoiceOriginalText)){$invoiceOriginalMessages=isset($nativeAccess)?(new \Kulturhus\Native\Language\Catalog($db,$nativeAccess))->messages():[];$invoiceOriginalText=static fn(string$s,array$v=[]):string=>\Kulturhus\Native\Language\InvoiceOriginalMessages::text($s,$invoiceOriginalMessages,$v);}
$positionDetails=\Kulturhus\Verein\InvoicePositionReview::details($db,(string)$_SESSION['actor'],$supplierEntryId);$positionItemLinks=\Kulturhus\Verein\InvoicePositionReview::forEntry($db,(string)$_SESSION['actor'],$supplierEntryId);$positionLabels=$positionDetails?\Kulturhus\Verein\InvoicePositionReview::originalDescriptions($db,(string)$_SESSION['actor'],$supplierEntryId):[];$canCreateFromPosition=(new \Kulturhus\Verein\Inventory($db,(string)$_SESSION['actor']))->canWrite()&&$finance->canWrite();
?>
<?php if($positionDetails):?><details class="invoice-saved-positions" data-invoice-original-items><summary><?=e($invoiceOriginalText('Rechnungsartikel und zugeordnete Gegenstände'))?></summary><p><?=e($invoiceOriginalText('Hier stehen die ursprünglich geprüften Artikelangaben. Die aktuelle Kontierung steht gesondert unter den zusätzlichen Buchhaltungsangaben.'))?></p>
<?php foreach($positionDetails as$positionRecord):$pd=$positionRecord['details'];$unitGross=$pd['unit_price_cents']===null?null:($pd['price_basis']==='gross'?$pd['unit_price_cents']:(int)round($pd['unit_price_cents']*(100+$pd['tax_rate'])/100));$unitNet=$pd['unit_price_cents']===null?null:($pd['price_basis']==='net'?$pd['unit_price_cents']:(int)round($pd['unit_price_cents']*100/(100+$pd['tax_rate'])));$linkedToPosition=array_values(array_filter($positionItemLinks,static fn($link):bool=>(int)$link['ordinal']===(int)$positionRecord['ordinal']));$originalLabel=$positionLabels[$positionRecord['ordinal']]??null;$positionDraftAvailable=false;if($canCreateFromPosition&&!$linkedToPosition){try{$positionDraft=\Kulturhus\Verein\InvoiceInventoryDraft::position($db,(string)$_SESSION['actor'],$supplierEntryId,(int)$positionRecord['ordinal']);$positionDraftAvailable=$positionDraft['existing']===''&&!$positionDraft['integrated_original'];}catch(DomainException){}}
?>
<section data-invoice-original-item><h4><?=e($invoiceOriginalText('Artikel {ordinal}',['ordinal'=>$positionRecord['ordinal']]))?><?php if($originalLabel!==null&&$originalLabel!==''):?> · <span data-invoice-original-description><?=e($originalLabel)?></span><?php endif?></h4>
<?php if($originalLabel===null||$originalLabel===''):?><p class="muted"><?=e($invoiceOriginalText('Ursprünglicher Artikeltext nicht gesondert gespeichert. Mit dem Original vergleichen.'))?></p><?php endif?>
<p><?=e($invoiceOriginalText('Menge:'))?> <?=e($pd['quantity'].' '.$pd['unit'])?> · <?=e($invoiceOriginalText('Einzelpreis:'))?> <?php if($unitGross===null):?><?=e($invoiceOriginalText('nicht gesondert erfasst'))?><?php else:?><?=e(euro($unitNet))?> <?=e($invoiceOriginalText('netto'))?> / <?=e(euro($unitGross))?> <?=e($invoiceOriginalText('brutto'))?> (<?=e($invoiceOriginalText('auf Cent gerundet'))?>)<?php endif?></p>
<p><?=e($invoiceOriginalText('Positionsbetrag netto'))?> <?=e(euro($pd['net_cents']))?> · <?=e($invoiceOriginalText('Steuer'))?> <?=(int)$pd['tax_rate']?> %: <?=e(euro($pd['gross_cents']-$pd['net_cents']))?> · <strong><?=e($invoiceOriginalText('Brutto'))?> <?=e(euro($pd['gross_cents']))?></strong></p>
<?php if(isset($pd['tax_rounding_delta'])):?><p><?=e($invoiceOriginalText('Bestätigte Steuer-Rundung: ursprünglich {calculated}, zugeordnet {allocated}; Gesamtsteuer laut Original {total}.',['calculated'=>euro($pd['calculated_tax_cents']),'allocated'=>euro($pd['allocated_tax_cents']),'total'=>euro($pd['invoice_tax_total_cents'])]))?></p><?php endif?>
<?php if(($pd['calculation_note']??'')!==''):?><p class="invoice-original-text" data-invoice-original-note><?=e($pd['calculation_note'])?></p><?php endif?>
<?php foreach($linkedToPosition as$linkedItem):?><p><?=e($invoiceOriginalText('Im Inventar:'))?> <?php if($linkedItem['can_open']):?><a class="btn btn-outline theme-secondary button secondary" href="<?=e(url(['view'=>'inventory','tab'=>'items','item'=>$linkedItem['item_id']]))?>"><?=e($linkedItem['label'])?></a><?php else:?><?=e($invoiceOriginalText('Gegenstand – kein aktueller Zugriff'))?><?php endif?></p><?php endforeach?>
<?php if($positionDraftAvailable):?><p><a class="btn btn-outline theme-secondary button secondary" data-invoice-original-create href="<?=e(url(['view'=>'inventory','tab'=>'items','new_item'=>1,'create_mode'=>'quantity','source'=>'expense:'.$supplierEntryId,'invoice_position'=>$positionRecord['ordinal']]))?>"><?=e($invoiceOriginalText('Gegenstand aus dieser Position anlegen'))?></a></p><?php endif?>
<?php if(($pd['source_hint']??'')!==''):?><details><summary><?=e($invoiceOriginalText('Hinweis aus Erfassungsentwurf'))?></summary><p class="invoice-original-text" data-invoice-original-hint><?=e($pd['source_hint'])?></p></details><?php endif?></section><?php endforeach?></details><?php endif?>
<?php if(!$positionDetails&&$positionItemLinks):?><details data-invoice-original-items><summary><?=e($invoiceOriginalText('Zugeordnete Gegenstände'))?></summary><?php foreach($positionItemLinks as$linkedItem):?><p><?=e($invoiceOriginalText('Position {ordinal}',['ordinal'=>$linkedItem['ordinal']]))?> · <?=e($linkedItem['description'])?> → <?php if($linkedItem['can_open']):?><a href="<?=e(url(['view'=>'inventory','tab'=>'items','item'=>$linkedItem['item_id']]))?>"><?=e($linkedItem['label'])?></a><?php else:?><?=e($invoiceOriginalText('Gegenstand – kein aktueller Zugriff'))?><?php endif?></p><?php endforeach?></details><?php endif?>
